INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginnen alle Multicast-Adressen mit FF00::/8?', 2, '[{"text": "Ja", "correct": true, "because": "Standard für IPv6-Multicast"}, {"text": "Nein", "correct": false, "because": "Festgelegt im Protokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits definieren den Präfix FF00::/8?', 3, '[{"text": "8", "correct": true, "because": "/8 markiert die ersten 8 Bits"}, {"text": "16", "correct": false, "because": "Zu hoch für Präfix"}, {"text": "64", "correct": false, "because": "Typisch für Interface-ID"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Zweck hat eine Adresse wie FF02::1?', 4, '[{"text": "Gruppenkommunikation", "correct": true, "because": "Multicast für alle Knoten"}, {"text": "Einzelgeräte", "correct": false, "because": "Unicast-spezifisch"}, {"text": "Globale Routing", "correct": false, "because": "Nicht einzeln routbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FF00::/8 ist für Gruppen. b) FF02::1 ist link-lokal.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) definiert Multicast, b) ist Scope"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von FF00::/8?', 5, '[{"text": "Einzeladressierung", "correct": true, "because": "Multicast ist gruppenbezogen"}, {"text": "Präfix FF00", "correct": false, "because": "Definiert Typ"}, {"text": "Scope-Bits", "correct": false, "because": "Bestimmen Reichweite"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob FF00::/8 für Unicast genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Nur für Multicast"}, {"text": "Ja", "correct": false, "because": "Falscher Adresstyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wähle ich für alle Geräte im lokalen Link?', 3, '[{"text": "FF02::1", "correct": true, "because": "Link-lokaler Multicast"}, {"text": "FF00::1", "correct": false, "because": "Zu allgemein"}, {"text": "2001:db8::1", "correct": false, "because": "Global Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat FF00::/8?', 5, '[{"text": "Gruppenadressierung", "correct": true, "because": "Multicast-Zweck"}, {"text": "Scope-definiert", "correct": true, "because": "Reichweite wie FF02"}, {"text": "Einzelrouting", "correct": false, "because": "Nicht Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) FF02::2 ist für Router. b) FF00::/8 ist global routbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, Multicast nicht einzeln routbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Multicast-Adresse?', 4, '[{"text": "Präfix FF00", "correct": false, "because": "Definiert Multicast"}, {"text": "Scope-Wert", "correct": false, "because": "Bestimmt Reichweite"}, {"text": "Einzelgeräte-ID", "correct": true, "because": "Gruppenbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist FF05::1 für alle Knoten?', 2, '[{"text": "Nein", "correct": true, "because": "Site-lokal, nicht alle"}, {"text": "Ja", "correct": false, "because": "FF02::1 ist link-lokal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Teile definieren eine Adresse wie FF02::1?', 4, '[{"text": "Präfix FF00", "correct": true, "because": "Multicast-Kennung"}, {"text": "Scope 2", "correct": true, "because": "Link-lokal"}, {"text": "Interface-ID", "correct": false, "because": "Nicht gerätespezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass FF00::/8 wie Broadcast ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Multicast ist gruppenspezifisch"}, {"text": "Ja", "correct": false, "because": "Ähnlich, aber gezielt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei FF00::/8?', 3, '[{"text": "Gruppenreichweite", "correct": true, "because": "Scope definiert Ziel"}, {"text": "Einzeladressen", "correct": false, "because": "Nicht relevant"}, {"text": "Kürzungsregeln", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FF02::1 ist link-lokal. b) FF00::/8 ist für Einzelgeräte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, Multicast"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet FF00::/8?', 5, '[{"text": "Effiziente Gruppenkommunikation", "correct": true, "because": "Weniger Traffic"}, {"text": "Flexible Reichweite", "correct": true, "because": "Scope wie FF02, FF05"}, {"text": "Globale Eindeutigkeit", "correct": false, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei FF00::/8 unwichtig?', 3, '[{"text": "Präfix FF00", "correct": false, "because": "Definiert Typ"}, {"text": "Scope", "correct": false, "because": "Bestimmt Reichweite"}, {"text": "Host-spezifische ID", "correct": true, "because": "Gruppenbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann FF00::/8 einzeln geroutet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Multicast, nicht Unicast"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob FF02::2 für alle Router ist?', 3, '[{"text": "Ja", "correct": true, "because": "Link-lokale Router"}, {"text": "Nein", "correct": false, "because": "Standard-Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wähle ich für site-lokale Gruppen?', 4, '[{"text": "FF05::1", "correct": true, "because": "Site-lokaler Scope"}, {"text": "FF02::1", "correct": false, "because": "Link-lokal"}, {"text": "2001:db8::1", "correct": false, "because": "Unicast"}]');
